package regression

import ("database/sql"; "errors"; "testing"; "time"; "github.com/jb843051627/bell-foundry/internal/model"; "github.com/jb843051627/bell-foundry/internal/store"; "github.com/jb843051627/bell-foundry/internal/service")

func TestBug30_TransactionRollback(t *testing.T) { repo, err := store.Open(t.TempDir()+"/foundry.db"); if err != nil { t.Fatal(err) }; defer repo.Close(); sentinel := errors.New("second step failed"); err = repo.Transaction(func(tx *sql.Tx) error { _, execErr := tx.Exec("INSERT INTO records(kind,id,payload,updated_at) VALUES('heat','partial','{}','now')"); if execErr != nil { return execErr }; return sentinel }); if !errors.Is(err, sentinel) { t.Fatal("transaction error identity lost") }; result := make(chan error, 1); go func() { var value map[string]any; result <- repo.Load("heat", "partial", &value) }(); select { case loadErr := <-result: if loadErr == nil { t.Fatal("partial write survived failed transaction") }; case <-time.After(300*time.Millisecond): t.Fatal("transaction connection was not released") }; if !errors.Is(service.PersistInspectionResult(sentinel), sentinel) { t.Fatal("inspection error identity lost") }; _ = model.ErrNotFound }
